import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '근태 담당자';

const COLUMNS = `
  employee_attendance_setting_id AS "employeeAttendanceSettingId",
  employee_id AS "employeeId",
  attendance_type_id AS "attendanceTypeId",
  attendance_criteria_id AS "attendanceCriteriaId",
  to_char(apply_start_date, 'YYYY-MM-DD') AS "applyStartDate"
`;

function idOf(value: unknown, label: string): string {
  if (value === undefined || value === null || value === '') {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label}을(를) 입력해 주세요.`);
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${label}이(가) 올바르지 않습니다.`);
  }
  return text;
}

function optionalDateOf(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '적용 시작일 형식이 올바르지 않습니다.');
  }
  return text;
}

async function assertActiveMasters(db: any, typeId: string, criteriaId: string): Promise<void> {
  const types = await db.query(
    'SELECT use_yn AS "useYn" FROM attendance_type WHERE attendance_type_id = CAST(:id AS bigint)',
    { id: typeId },
  );
  if (types.length === 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '적용 근태항목을 찾을 수 없습니다.');
  }
  const criteria = await db.query(
    'SELECT use_yn AS "useYn" FROM attendance_criteria WHERE attendance_criteria_id = CAST(:id AS bigint)',
    { id: criteriaId },
  );
  if (criteria.length === 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '적용 근무시간 기준을 찾을 수 없습니다.');
  }
  if (types[0].useYn !== '사용' || criteria[0].useYn !== '사용') {
    throw new ApiError(422, 'INACTIVE_MASTER_DATA', '미사용 근태항목 또는 근태 기준정보는 선택할 수 없습니다.');
  }
}

@Controller('api/v1')
export class FnSfr01703Controller {
  @Get('/employee-attendance-settings')
  async listEmployeeAttendanceSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const employeeId = query['employeeId'] === undefined || query['employeeId'] === '' ? null : idOf(query['employeeId'], '임직원');
    const pageText = String(query['page'] ?? '0');
    const sizeText = String(query['size'] ?? '20');
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    return transaction(async (db) => {
      const where = 'CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint)';
      const totals = await db.query(
        `SELECT COUNT(*) AS "total" FROM employee_attendance_setting WHERE ${where}`,
        { employeeId },
      );
      const items = await db.query(
        `SELECT ${COLUMNS} FROM employee_attendance_setting WHERE ${where}
         ORDER BY employee_attendance_setting_id DESC
         LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { employeeId, size, offset: page * size },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }

  @Post('/employee-attendance-settings')
  @HttpCode(200)
  async createEmployeeAttendanceSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const employeeId = idOf(data['employeeId'], '임직원');
    const typeId = idOf(data['attendanceTypeId'], '적용 근태항목');
    const criteriaId = idOf(data['attendanceCriteriaId'], '적용 근무시간 기준');
    const applyStartDate = optionalDateOf(data['applyStartDate']);
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
        { id: employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원을 찾을 수 없습니다.');
      }
      await assertActiveMasters(db, typeId, criteriaId);
      // 가정: 적용 시작일 미입력 시 현재 일자
      const duplicated = await db.query(
        `SELECT employee_attendance_setting_id FROM employee_attendance_setting
         WHERE employee_id = CAST(:employeeId AS bigint)
           AND attendance_type_id = CAST(:typeId AS bigint)
           AND apply_start_date = COALESCE(CAST(:applyStartDate AS date), CAST(now() AS date))`,
        { employeeId, typeId, applyStartDate },
      );
      if (duplicated.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 임직원·근태항목·적용 시작일의 설정이 이미 있습니다.');
      }
      const rows = await db.query(
        `INSERT INTO employee_attendance_setting
           (employee_id, attendance_type_id, attendance_criteria_id, apply_start_date, created_at, updated_at)
         VALUES
           (CAST(:employeeId AS bigint), CAST(:typeId AS bigint), CAST(:criteriaId AS bigint),
            COALESCE(CAST(:applyStartDate AS date), CAST(now() AS date)), now(), now())
         RETURNING ${COLUMNS}`,
        { employeeId, typeId, criteriaId, applyStartDate },
      );
      return rows[0];
    });
  }

  @Put('/employee-attendance-settings/:employeeAttendanceSettingId')
  async updateEmployeeAttendanceSetting(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const settingId = idOf(req.params['employeeAttendanceSettingId'], '설정 ID');
    const data = checks.inputOf(req.body);
    const typeId = idOf(data['attendanceTypeId'], '적용 근태항목');
    const criteriaId = idOf(data['attendanceCriteriaId'], '적용 근무시간 기준');
    const applyStartDate = optionalDateOf(data['applyStartDate']);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT employee_id AS "employeeId",
                to_char(apply_start_date, 'YYYY-MM-DD') AS "applyStartDate"
         FROM employee_attendance_setting
         WHERE employee_attendance_setting_id = CAST(:id AS bigint)`,
        { id: settingId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_ATTENDANCE_SETTING_NOT_FOUND', '설정을 찾을 수 없습니다.');
      }
      await assertActiveMasters(db, typeId, criteriaId);
      const duplicated = await db.query(
        `SELECT employee_attendance_setting_id FROM employee_attendance_setting
         WHERE employee_id = CAST(:employeeId AS bigint)
           AND attendance_type_id = CAST(:typeId AS bigint)
           AND apply_start_date = COALESCE(CAST(:applyStartDate AS date), apply_start_date)
           AND employee_attendance_setting_id <> CAST(:id AS bigint)`,
        { employeeId: String(found[0].employeeId), typeId, applyStartDate, id: settingId },
      );
      if (duplicated.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 임직원·근태항목·적용 시작일의 설정이 이미 있습니다.');
      }
      const rows = await db.query(
        `UPDATE employee_attendance_setting SET
           attendance_type_id = CAST(:typeId AS bigint),
           attendance_criteria_id = CAST(:criteriaId AS bigint),
           apply_start_date = COALESCE(CAST(:applyStartDate AS date), apply_start_date),
           updated_at = now()
         WHERE employee_attendance_setting_id = CAST(:id AS bigint)
         RETURNING ${COLUMNS}`,
        { typeId, criteriaId, applyStartDate, id: settingId },
      );
      return rows[0];
    });
  }
}

