import { useState } from 'react';
import {
  call,
  useData,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  DateInput,
  DateText,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

export default function FnSfr01703Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [query, setQuery] = useState<{ employeeId: number | string; page: number }>({ employeeId: '', page: 0 });
  const [editing, setEditing] = useState<Row | 'new' | null>(null);
  const [typeId, setTypeId] = useState<number | string>('');
  const [criteriaId, setCriteriaId] = useState<number | string>('');
  const [startDate, setStartDate] = useState('');
  const [newEmployeeId, setNewEmployeeId] = useState<number | string>('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/employee-attendance-settings', role, undefined, { employeeId: query.employeeId, page: query.page, size: 20 }),
    [query.employeeId, query.page],
  );

  function openNew() {
    setNewEmployeeId('');
    setTypeId('');
    setCriteriaId('');
    setStartDate('');
    setEditing('new');
  }

  function openEdit(row: Row) {
    setTypeId(row.attendanceTypeId as number);
    setCriteriaId(row.attendanceCriteriaId as number);
    setStartDate(String(row.applyStartDate ?? ''));
    setEditing(row);
  }

  async function submit() {
    if (typeId === '' || criteriaId === '') {
      throw new Error('적용 근태항목과 적용 근무시간 기준을 선택해 주세요.');
    }
    if (editing === 'new') {
      if (newEmployeeId === '') {
        throw new Error('임직원을 선택해 주세요.');
      }
      await call('POST', '/employee-attendance-settings', role, {
        employeeId: newEmployeeId,
        attendanceTypeId: typeId,
        attendanceCriteriaId: criteriaId,
        applyStartDate: startDate,
      });
      notify('등록했습니다.');
    } else if (editing) {
      await call('PUT', `/employee-attendance-settings/${editing.employeeAttendanceSettingId}`, role, {
        attendanceTypeId: typeId,
        attendanceCriteriaId: criteriaId,
        applyStartDate: startDate,
      });
      notify('수정했습니다.');
    }
    setEditing(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>설정 건수</h2>
        <Tiles items={[['조회된 설정', data ? data.total : 0]]} />
      </section>
      <section className="box span-8">
        <h2>임직원 근태 적용 설정</h2>
        <Filters
          onSearch={() => setQuery({ employeeId, page: 0 })}
          onReset={() => {
            setEmployeeId('');
            setQuery({ employeeId: '', page: 0 });
          }}
        >
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={openNew}>설정 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={data?.items ?? []}
          empty="등록된 설정이 없습니다."
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'attendanceTypeId', label: '적용 근태항목', render: (r) => <RefName table="attendance_type" role={role} value={r.attendanceTypeId} /> },
            { key: 'attendanceCriteriaId', label: '적용 근무시간 기준', render: (r) => <RefName table="attendance_criteria" role={role} value={r.attendanceCriteriaId} /> },
            { key: 'applyStartDate', label: '적용 시작일', render: (r) => <DateText value={r.applyStartDate} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    openEdit(r);
                  }}
                >
                  수정
                </button>
              ),
            },
          ]}
          onRowClick={openEdit}
        />
        <Pager
          page={data?.page ?? 0}
          size={data?.size ?? 20}
          total={data?.total ?? 0}
          onPage={(p) => setQuery({ ...query, page: p })}
        />
      </section>
      {editing ? (
        <Drawer title={editing === 'new' ? '근태 적용 설정 등록' : '근태 적용 설정 수정'} onClose={() => setEditing(null)}>
          <Form onSubmit={submit} submit={editing === 'new' ? '등록' : '저장'}>
            {editing === 'new' ? (
              <Field label="임직원" required>
                <LookupSelect table="employee" role={role} value={newEmployeeId} onChange={setNewEmployeeId} />
              </Field>
            ) : (
              <Field label="임직원">
                <RefName table="employee" role={role} value={editing.employeeId} />
              </Field>
            )}
            <Field label="적용 근태항목" required>
              <LookupSelect table="attendance_type" role={role} value={typeId} onChange={setTypeId} />
            </Field>
            <Field label="적용 근무시간 기준" required>
              <LookupSelect table="attendance_criteria" role={role} value={criteriaId} onChange={setCriteriaId} />
            </Field>
            <Field label="적용 시작일" hint="비우면 오늘 날짜로 등록합니다.">
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
